local ECSComponent = import("Frame.ECS.ECSComponent")

---@class DailyQuestComponent
local DailyQuestComponent = Class("DailyQuestComponent", ECSComponent)
local DailyQuestDojo = import("Game.Dojo.DailyQuestDojo")
local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule

function DailyQuestComponent:__init()
    self._dailyQuests = {}               --所有的关卡信息
    self._ticketsNum = nil       --门票数量
    self._ticketsRecoverTime = nil --距离下一张门票恢复时间
end

function DailyQuestComponent:__delete()
    self._dailyQuests = nil
    self._ticketsNum = nil       --门票数量
    self._ticketsRecoverTime = nil --距离下一张门票恢复时间
end

function DailyQuestComponent:DailyQuestHomeReq(cb)
    GameUtils.Request(Interfaces.OverseaRegionalMapDailyQuestHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._dailyQuests = {}
        for k, v in pairs(jsonData.info) do
            self._dailyQuests[checkString(v.type)] = v
        end
        self._ticketsNum = checkNumber(jsonData.spHp)            
        self._ticketsRecoverTime = checkNumber(jsonData.spRecoverTime)            
        self:StartTimeDown()

        if cb then
            cb()
        end
    end)
end

--恢复时间
function DailyQuestComponent:GetTicketsRecoverTime()
    return self._ticketsRecoverTime
end

--门票数量
function DailyQuestComponent:GetCurTicketCount()
    return self._ticketsNum
end

function DailyQuestComponent:AddTicketCount(num)
    self._ticketsNum = checkNumber(self._ticketsNum) + num
end

function DailyQuestComponent:ConsumeTicket(num)
    self._ticketsNum = checkNumber(self._ticketsNum) - (num or 1)
end

function DailyQuestComponent:StartTimeDown()
    self:ClearTimeDown()
    local maxNum = ActionUtils.GetDailyQuestMaxTicketNum()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        if self._ticketsNum < maxNum then
            self._ticketsRecoverTime = self._ticketsRecoverTime - 1
            if self._ticketsRecoverTime == 0 then
                self._ticketsNum = self._ticketsNum + 1
                Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, nil)
            elseif self._ticketsRecoverTime < 0 then
                self._ticketsRecoverTime = ActionUtils.GetDailyQuestTicketAddTime()
            end
        else
            self._ticketsRecoverTime = 0
        end
    end, CountDownTime, false, true)
end

function DailyQuestComponent:ClearTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function DailyQuestComponent:GetDailyQuestData(type)
    return self._dailyQuests[checkString(type)]
end

---UpdateNewDailyQuestID 更新日常副本的最新关卡
---@param questId string 关卡id
function DailyQuestComponent:UpdateNewDailyQuestID(questId, guarantee)
    if not questId then
        return
    end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return
    end

    local data = self:GetDailyQuestData(vo.type)

    if checkNumber(data.newestPassedQuest) < checkNumber(questId) then
        self._dailyQuests[checkString(vo.type)].newestPassedQuest = checkString(questId)
    end
    self._dailyQuests[checkString(vo.type)].guarantee = checkNumber(guarantee)
end

---IsPassLevelById 是否通关关卡
---@param questId string 关卡id 
function DailyQuestComponent:IsPassLevelById(questId)
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return
    end
    local data = self:GetDailyQuestData(vo.type)

    return checkNumber(data.newestPassedQuest) >= questId
end

return DailyQuestComponent